// Offline support for the installed app. Generated by tools/dexpage: CACHE changes whenever the page does,
// so a regenerated page replaces the old copy on the next online visit.
const CACHE = "dex-cdf2a73af87a";
const FILES = ["./", "index.html", "manifest.webmanifest", "icon-192.png", "icon-512.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("dex-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  if (req.mode === "navigate") {
    // Network first so players see new data when online; fall back to the cached page offline.
    event.respondWith(
      fetch(req)
        .then((res) => {
          // Only a real copy of the page may replace the offline one (never a 404 page or redirect)
          const url = new URL(req.url);
          const isPage = url.pathname.endsWith("/") || url.pathname.endsWith("/index.html");
          if (res.ok && res.type === "basic" && isPage) {
            const copy = res.clone();
            caches.open(CACHE).then((cache) => cache.put("index.html", copy));
          }
          return res;
        })
        .catch(() => caches.match("index.html"))
    );
    return;
  }
  event.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
});
